// Generated by WATX Compiler
// WAT + HTML = WATX — A reactive UI framework in WebAssembly

import { createRuntime } from './watx-runtime.js';

export async function createApp(wasmUrl) {
  const runtime = createRuntime();
  const { createSignal, createEffect, batch, h, text, mount } = runtime;

  // Load WebAssembly module
  const wasmResponse = await fetch(wasmUrl);
  const wasmBytes = await wasmResponse.arrayBuffer();
  const wasmModule = await WebAssembly.instantiate(wasmBytes, {});
  const wasm = wasmModule.instance.exports;

  // Create reactive signals backed by WASM globals
  const [celsius, set_celsius] = createSignal(
    () => wasm.signal_get_celsius(),
    (v) => wasm.signal_set_celsius(v),
    0
  );
  const [fahrenheit, set_fahrenheit] = createSignal(
    () => wasm.signal_get_fahrenheit(),
    (v) => wasm.signal_set_fahrenheit(v),
    32
  );

  // Component: TemperatureConverter
  function render_TemperatureConverter() {
    const el_div_0 = h('div');
    el_div_0.setAttribute('class', 'converter');
    const el_h2_1 = h('h2');
    const txt_2 = text('Temperature Converter');
    el_h2_1.appendChild(txt_2);
    el_div_0.appendChild(el_h2_1);
    const el_div_3 = h('div');
    el_div_3.setAttribute('class', 'row');
    const el_label_4 = h('label');
    const txt_5 = text('Celsius');
    el_label_4.appendChild(txt_5);
    el_div_3.appendChild(el_label_4);
    const el_span_6 = h('span');
    el_span_6.setAttribute('class', 'value');
    const reactive_7 = text('');
    createEffect(() => {
      reactive_7.textContent = String(celsius());
    });
    el_span_6.appendChild(reactive_7);
    el_div_3.appendChild(el_span_6);
    const el_div_8 = h('div');
    el_div_8.setAttribute('class', 'buttons');
    const el_button_9 = h('button');
    el_button_9.addEventListener('click', (e) => {
      set_celsius((celsius() - 1));
    });
    const txt_10 = text('-');
    el_button_9.appendChild(txt_10);
    el_div_8.appendChild(el_button_9);
    const el_button_11 = h('button');
    el_button_11.addEventListener('click', (e) => {
      set_celsius((celsius() + 1));
    });
    const txt_12 = text('+');
    el_button_11.appendChild(txt_12);
    el_div_8.appendChild(el_button_11);
    el_div_3.appendChild(el_div_8);
    el_div_0.appendChild(el_div_3);
    const el_div_13 = h('div');
    el_div_13.setAttribute('class', 'row');
    const el_label_14 = h('label');
    const txt_15 = text('Fahrenheit');
    el_label_14.appendChild(txt_15);
    el_div_13.appendChild(el_label_14);
    const el_span_16 = h('span');
    el_span_16.setAttribute('class', 'value');
    const reactive_17 = text('');
    createEffect(() => {
      reactive_17.textContent = String(fahrenheit());
    });
    el_span_16.appendChild(reactive_17);
    el_div_13.appendChild(el_span_16);
    el_div_0.appendChild(el_div_13);
    return el_div_0;
  }

  return {
    TemperatureConverter: render_TemperatureConverter,
    mount,
    runtime,
    wasm,
  };
}